","/**
 * Field extraction utilities for the BNB Evaluation Form.
 * Provides helper functions to compute derived field values.
 */

/**
 * Computes the NPS category based on the numeric score.
 * @param score - NPS score from 0 to 10
 * @returns "detractor" | "neutral" | "promoter"
 */
export function getNpsCategory(score: number): string {
 if (score <= 6) return "detractor";
 if (score <= 8) return "neutral";
 return "promoter";
}

/**
 * Formats a Date object to ServiceNow datetime format.
 * @param date - The date to format
 * @returns Formatted string "yyyy-MM-dd HH:mm:ss"
 */
export function formatDateTime(date: Date): string {
 const pad = (n: number) => n.toString().padStart(2, "0");
 const year = date.getFullYear();
 const month = pad(date.getMonth() + 1);
 const day = pad(date.getDate());
 const hours = pad(date.getHours());
 const minutes = pad(date.getMinutes());
 const seconds = pad(date.getSeconds());
 return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
}

/**
 * Validates that all required evaluation fields are filled.
 */
export function isFormValid(
 starRating: number,
 demandResolved: boolean | null,
 npsScore: number | null
): boolean {
 return starRating > 0 && demandResolved !== null && npsScore !== null;
}
