","import React, { useState, useEffect, useCallback } from "react";
import DashboardView from "./components/DashboardView";
import ListView from "./components/ListView";

interface ViewState {
 view: string;
}

function getViewFromUrl(): ViewState {
 const params = new URLSearchParams(window.location.search);
 return { view: params.get("view") || "dashboard" };
}

export default function App() {
 const [currentView, setCurrentView] = useState<ViewState>(getViewFromUrl);

 useEffect(() => {
 const onPopState = () => setCurrentView(getViewFromUrl());
 window.addEventListener("popstate", onPopState);
 return () => window.removeEventListener("popstate", onPopState);
 }, []);

 const navigateToView = useCallback((viewName: string, title?: string) => {
 const params = new URLSearchParams({ view: viewName });
 const relativePath = `${window.location.pathname}?${params}`;
 const pageTitle = title || `Painel Admin - ${viewName}`;

 if (window.self !== window.top) {
 (window as any).CustomEvent.fireTop("magellanNavigator.permalink.set", {
 relativePath,
 title: pageTitle
 });
 }

 window.history.pushState({ viewName }, "", relativePath);
 document.title = pageTitle;
 setCurrentView({ view: viewName });
 }, []);

 const { view } = currentView;

 if (view === "list") {
 return <ListView onNavigate={navigateToView} />;
 }

 return <DashboardView onNavigate={navigateToView} />;
}
